// File: app.js
// HTTP entry point: registers every route.
const express = require('express');

const app = express();
app.use(express.json());

app.get('/search', require('./routes/search'));
app.get('/version', require('./routes/version'));
app.get('/health', require('./routes/health'));
app.post('/submitted-comment-preview', require('./routes/submitted-comment-preview'));

module.exports = app;

// File: routes/health.js
// Reports that the service is up and how long it has been running.
const startedAt = Date.now();

module.exports = function handler(req, res) {
  res.json({ status: 'ok', uptimeSeconds: Math.round((Date.now() - startedAt) / 1000) });
};

// File: routes/search.js
// Shows the search page with the query echoed back.
function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

module.exports = function handler(req, res) {
  const q = req.query.q || '';
  res.send(`<h1>Search</h1><p>Results for "${escapeHtml(q)}"</p><ul></ul>`);
};

// File: routes/submitted-comment-preview.js
// Echoes a submitted comment back as a preview.
const { renderMessage } = require('../lib/views');
module.exports = function handler(req, res) {
  const comment = renderMessage(req);
  res.write('<div class="preview">');
  res.write(comment);
  res.end('</div>');
};

// File: routes/version.js
// Reports the deployed git revision.
const { execFile } = require('child_process');

module.exports = function handler(req, res) {
  execFile('git', ['rev-parse', '--short', 'HEAD'], (err, stdout) => {
    res.json({ revision: err ? 'unknown' : String(stdout).trim() });
  });
};

// File: lib/views.js
// HTML snippets used by the routes.
function renderMessage(req) {
  return req.body.comment;
}

module.exports = { renderMessage };
